// Cricket auction — one Worker, one Durable Object, nothing else to configure.
// The game page is embedded below so there is no static-asset setup to get wrong.

const PAGE_B64 = "";

let PAGE = null;
function page() {
  if (!PAGE) {
    const bin = atob(PAGE_B64);
    const bytes = new Uint8Array(bin.length);
    for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
    PAGE = bytes;
  }
  return PAGE;
}

function merge(a, b) {
  const o = { ...(a || {}) };
  for (const k in b) {
    const v = b[k];
    if (v && typeof v === "object" && !Array.isArray(v) &&
        o[k] && typeof o[k] === "object" && !Array.isArray(o[k])) o[k] = merge(o[k], v);
    else o[k] = v;
  }
  return o;
}

export class AuctionRoom {
  constructor(state) {
    this.state = state;
    this.docs = null;
    this.state.blockConcurrencyWhile(async () => {
      this.docs = (await this.state.storage.get("docs")) || {};
    });
  }
  bcast(path) {
    const msg = JSON.stringify({ t: "doc", p: path, d: this.docs[path] ?? null });
    for (const ws of this.state.getWebSockets()) { try { ws.send(msg); } catch (e) {} }
  }
  async fetch(req) {
    if (req.headers.get("Upgrade") !== "websocket")
      return new Response("expected websocket", { status: 426 });
    const [client, server] = Object.values(new WebSocketPair());
    this.state.acceptWebSocket(server);
    for (const p in this.docs)
      try { server.send(JSON.stringify({ t: "doc", p, d: this.docs[p] })); } catch (e) {}
    try { server.send(JSON.stringify({ t: "ready" })); } catch (e) {}
    return new Response(null, { status: 101, webSocket: client });
  }
  async webSocketMessage(ws, raw) {
    let m; try { m = JSON.parse(raw); } catch (e) { return; }
    if (!m || typeof m.p !== "string" || m.p.length > 120) return;
    if (m.t === "ping") { try { ws.send('{"t":"pong"}'); } catch (e) {} return; }
    if (m.t === "set") this.docs[m.p] = m.d;
    else if (m.t === "update") this.docs[m.p] = merge(this.docs[m.p] || {}, m.d);
    else return;
    this.bcast(m.p);
    await this.state.storage.put("docs", this.docs);
  }
  async webSocketClose(ws) { try { ws.close(); } catch (e) {} }
  async webSocketError(ws) { try { ws.close(); } catch (e) {} }
}

export default {
  async fetch(request, env) {
    const url = new URL(request.url);
    const m = url.pathname.match(/^\/room\/([A-Za-z0-9]{3,8})$/);
    if (m) {
      const id = env.ROOMS.idFromName(m[1].toUpperCase());
      return env.ROOMS.get(id).fetch(request);
    }
    return new Response(page(), {
      headers: {
        "content-type": "text/html; charset=utf-8",
        "cache-control": "no-cache",
      },
    });
  },
};
